#!/usr/bin/env node
// PRM-003 Part F report: task walks, ISO 9241-110 rule-based ratings, matrices, and task hops per IA option.
// Writes deep/task-flows.md and deep/data/task-summary.json.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const deep = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../deep');
const { walks, urlState } = JSON.parse(fs.readFileSync(path.join(deep, 'data/task-walks.json'), 'utf8'));
const t = (h, r) => [`| ${h.join(' | ')} |`, `|${h.map(() => '---').join('|')}|`, ...r.map(x => `| ${x.join(' | ')} |`)].join('\n');
const pageOf = u => (u ?? '').split('?')[0].replace(/^\/admin\/.*/, '/admin');

const CONSOLIDATE = { '/cpm': 'Overview', '/cpm/performance': 'Overview', '/cpm/kpi': 'Overview', '/cpm/events': 'Episodes', '/cpm/explorer': 'Loop', '/cpm/historical': 'Loop', '/cpm/investigation': 'Loop', '/cpm/response': 'Loop', '/trend': 'Loop', '/cpm/evidence': 'Evidence', '/cpm/replay': 'Evidence', '/cpm/windows': 'Evidence', '/cpm/calculations': 'Evidence', '/cpm/registry': 'Setup', '/cpm/config': 'Setup', '/cpm/pipeline': 'System', '/cpm/governance': 'System', '/admin': 'System' };
const RESTRUCTURE = { ...CONSOLIDATE, '/cpm': 'L1 Plant', '/cpm/performance': 'L2 Unit', '/cpm/kpi': 'L2 Unit', '/cpm/events': 'L2 Unit', '/cpm/explorer': 'L3 Loop', '/cpm/historical': 'L3 Loop', '/trend': 'L3 Loop', '/cpm/investigation': 'L4 Diagnostics', '/cpm/response': 'L4 Diagnostics', '/cpm/evidence': 'L4 Diagnostics', '/cpm/replay': 'L4 Diagnostics', '/cpm/windows': 'L4 Diagnostics', '/cpm/calculations': 'L4 Diagnostics' };
const hopsIn = (w, map) => { const seq = w.hops.map(h => map[pageOf(h.url)] ?? pageOf(h.url)); return seq.filter((s, i) => i === 0 || s !== seq[i - 1]).length; };
const distinctPages = w => { const seq = w.hops.map(h => pageOf(h.url)); return seq.filter((s, i) => i === 0 || s !== seq[i - 1]).length; };

const rate = w => {
  const land = w.hops[w.hops.length - 1];
  const terms = land.internalTerms?.length ?? 0;
  return {
    suitability: w.deadEnds ? 'F' : land.words > 600 ? 'F' : 'P',
    selfDescription: terms >= 3 ? 'F' : 'P',
    conformity: w.contextLost.length ? 'F' : 'P',
    controllability: w.scrollPx > 500 ? 'F' : 'P',
  };
};
const rows = walks.map(w => {
  const r = rate(w);
  const land = w.hops[w.hops.length - 1];
  return [w.id, w.role, w.task, w.source, w.hops.map(h => pageOf(h.url).replace('/cpm/', '').replace('/cpm', 'overview')).join(' → '), distinctPages(w), w.clicks, w.scrollPx, land.words, (land.internalTerms ?? []).length, w.contextLost.join(', ') || '-', w.deadEnds, `${r.suitability} ${r.selfDescription} ${r.conformity} ${r.controllability}`];
});
const avg = f => +(walks.reduce((a, w) => a + f(w), 0) / walks.length).toFixed(2);
const fails = k => walks.filter(w => rate(w)[k] === 'F').length;
const summary = {
  tasks: walks.length, deadEnds: walks.filter(w => w.deadEnds).map(w => w.id), contextLost: walks.filter(w => w.contextLost.length).map(w => `${w.id}:${w.contextLost}`), avgWordsOnLanding: avg(w => w.hops[w.hops.length - 1].words),
  hops: { keep: avg(distinctPages), consolidate: avg(w => hopsIn(w, CONSOLIDATE)), restructure: avg(w => hopsIn(w, RESTRUCTURE)) },
  multiPage: { keep: walks.filter(w => distinctPages(w) > 1).length, consolidate: walks.filter(w => hopsIn(w, CONSOLIDATE) > 1).length, restructure: walks.filter(w => hopsIn(w, RESTRUCTURE) > 1).length },
  iso: { suitability: fails('suitability'), selfDescription: fails('selfDescription'), conformity: fails('conformity'), controllability: fails('controllability') },
  urlState,
};
fs.writeFileSync(path.join(deep, 'data/task-summary.json'), JSON.stringify(summary, null, 1));

const doc = `# CPA roles and task flows (Part F)

Walked on the production build by \`docs/theme/tools/task-walk.mjs\` with the write guard on. Generated by \`task-report.mjs\`.

## Roles

Described only from the guide (pp.11-13), the CPA navigation task groups and the permissions model. Assumptions are marked.

| Role | Need | Basis | Permissions seen |
|---|---|---|---|
| Control-room operator | Which loops need attention now, and the current state | Guide p.11; "Find problems" | \`analytics.view\`, \`historian.view\` |
| Control or process engineer | Investigate performance, trends, gates, evidence, response, tuning | Guide p.12-13; "Check a loop", "Understand the cause" | adds \`cpm.config.read\` *(assumed)* |
| Reliability or maintenance | Valve, actuator, instrument and NE107 follow-up | Guide p.12 related instrument links; KPI tiles | \`analytics.view\` *(assumed; no separate role exists)* |
| Administrator or SuperAdmin | Registry, configuration, governance, pipeline, users | "Set up"; CHG-081 | \`system.manage\`, \`admin.*\`, \`rbac.manage\` |

CPA has no Reliability role, so that row describes a need rather than an account type.

## Task walks

Columns: distinct pages visited, clicks that worked, scroll to reach the control in px, words on the landing page, internal terms on the landing page, context lost, dead ends, and ratings. Scripted durations are in \`data/task-walks.json\` but are not reported, because request pacing dominates them.

Ratings are rule-based, against ISO 9241-110, in the order suitability, self-descriptiveness, conformity, controllability. **F** is a fail: dead end or over 600 words on landing; 3 or more internal terms; context lost; over 500 px of scroll. Use-error robustness is not assessed, because no write was performed.

${t(['ID', 'Role', 'Task', 'Traced to', 'Path', 'Pages', 'Clicks', 'Scroll', 'Words', 'Internal', 'Lost', 'Dead ends', 'ISO'], rows)}

**Reading the table.** Walks follow the shortest route I could script, so they are a best case. A real user first has to know which of 14 pages to open. A dead end means the control did not exist in the lab state or the product: OP1 and RE6 need review data and alarm links, EN2 and EN3 could not find a labelled entry from the page.

Summary: average ${summary.hops.keep} pages per task; ${summary.avgWordsOnLanding} words on the landing page; rule failures: suitability ${summary.iso.suitability}, self-descriptiveness ${summary.iso.selfDescription}, conformity ${summary.iso.conformity}, controllability ${summary.iso.controllability}, out of ${walks.length}.

## Surface × role

P primary, S secondary, blank not used. Derived from the walks, the navigation groups and permissions.

${t(['Surface', 'Operator', 'Engineer', 'Reliability', 'Admin'], [
  ['Overview', 'P', 'S', 'S', 'S'], ['Performance', 'S', 'P', 'S', ''], ['Loop Events', 'S', 'P', 'P', ''], ['KPI drill-down', 'S', 'S', 'P', ''], ['Loop Explorer', 'P', 'P', 'S', ''], ['Historical', 'S', 'P', 'S', ''], ['Investigation', '', 'P', 'P', ''], ['Evidence Workbench', '', 'P', 'S', ''], ['Evidence Replay', '', 'P', '', ''], ['Window Inspector', 'S', 'P', '', ''], ['Calculations', '', 'P', '', ''], ['System Response', '', 'P', '', ''], ['Trend', 'S', 'P', 'S', ''], ['Loop Registry', '', 'S', 'S', 'P'], ['Gate Configuration', '', 'S', '', 'P'], ['Pipeline Health', '', '', '', 'P'], ['Governance', '', '', '', 'P'], ['Administration', '', '', '', 'P'],
])}

## Function overlap

${t(['Function', 'Where it appears', 'How the instances differ'], [
  ['PV, SP, OP trend', 'Overview (loop focus), Explorer, Investigation, Historical, Replay, Evidence, Response, /trend', '8 places on 5 chart builders (C1, C2, C3, C4, C11). Mode is drawn only on Historical. SP is dashed on 3 and solid on 2. Time zone differs by chart'],
  ['Gate results', 'Performance (checks and matrix), Explorer, Evidence, Calculations, Investigation, Windows', 'Different vocabularies: chips, matrix marks, chain stages, rows'],
  ['Loop KPIs', 'Overview tiles, KPI drill-down, Explorer cards, Historical overlay, Calculations, Windows', 'Five names for time in AUTO; different staleness rules'],
  ['Verdict explanation', 'Explorer summary, Investigation, Evidence explain panel', 'Three wordings of one verdict'],
  ['Loop selection', 'Explorer, Historical, Investigation, Evidence, Replay, Windows, Calculations, Response, Registry, Config', 'Each page repeats a loop picker plus site, area and unit filters'],
  ['Episodes', 'Loop Events, Overview trail, Explorer History, Investigation', 'Different filters and scope; the Overview trail ignores plant scope'],
  ['Readiness', 'Overview strip, Registry, Explorer banner, Performance tile', 'Different counts for one concept'],
  ['Time window', '12h and 24h toggle on 8 pages, range on Historical, profile on Windows, range on /trend', 'No shared selector'],
])}

## ISA-101 display hierarchy

${t(['Level', 'Purpose', 'Surfaces today', 'Gap'], [
  ['1 Overview', 'Plant-wide situation', 'Overview', 'Mixes a level 3 loop panel into level 1 when a loop is selected'],
  ['2 Unit or area', 'One area, what needs action', 'Performance, Loop Events, KPI drill-down', 'No true unit view: scope is a filter on plant-wide pages'],
  ['3 Loop detail', 'One loop, current and recent', 'Explorer, Historical, /trend', 'Split across three pages; only Historical aligns mode'],
  ['4 Diagnostic or support', 'Evidence and method', 'Investigation, Evidence, Replay, Windows, Calculations, Response', 'Six pages; Investigation mixes level 3 conclusions with level 4 evidence'],
  ['Support', 'Setup and platform', 'Registry, Configuration, Pipeline, Governance, Administration', 'Registry and Configuration sit in the operator task list'],
])}

## Task hops by page-structure option

Each walk replayed against the option's page map, counting a hop only when the destination changes. Tabs on one page do not count.

${t(['Option', 'Destinations', 'Average pages per task', 'Tasks needing more than one page'], [
  ['Keep', 18, summary.hops.keep, summary.multiPage.keep], ['Consolidate', 6, summary.hops.consolidate, summary.multiPage.consolidate], ['Restructure', 6, summary.hops.restructure, summary.multiPage.restructure],
])}
`;
fs.writeFileSync(path.join(deep, 'task-flows.md'), doc);
console.log(JSON.stringify(summary, null, 1));
